globalThis.identificationPhotos = (globalThis.identificationPhotos ?? []).concat([{"name":"Graceful coral seaweed","taxon":"Corallina vancouveriensis","photo":698733993,"observation":381846459,"license":"cc-by","credit":"(c) Johanna Marshall, some rights reserved (CC BY)","image":"","cue":"Look for small, finely branched, pink coralline tufts."},{"name":"Blue branching seaweed","taxon":"Gloiocladia laciniata","photo":240004368,"observation":140226640,"license":"cc-by","credit":"(c) Cricket Raspet, some rights reserved (CC BY)","image":"","cue":"Look for broad branches with lobed or divided tips. The underwater color can vary with lighting."},{"name":"Winged kelp","taxon":"Pterygophora californica","photo":744755232,"observation":405460634,"license":"cc0","credit":"no rights reserved","image":"","cue":"This California example has a long, stiff stipe with blades concentrated toward its upper end."},{"name":"Bead coral","taxon":"Calliarthron tuberculosum","photo":582343702,"observation":321960465,"license":"cc0","credit":"no rights reserved","image":"","cue":"Also called coarse bead coral. Look for rigid pink segments connected at narrow joints."},{"name":"Polly","taxon":"Polysiphonia pacifica","photo":221405262,"observation":130210103,"license":"cc-by-sa","credit":"(c) Bridgette Clarkston, some rights reserved (CC BY-SA)","image":"","directoryTaxon":"Polysiphonia spp.","cue":"Example: Polysiphonia pacifica, also called pretty polly. Look for a tuft of fine, reddish branching threads."},{"name":"Sea lettuce","taxon":"Ulva lactuca","photo":768151084,"observation":417042783,"license":"cc-by","credit":"(c) Luke Bistritz, some rights reserved (CC BY)","image":"","directoryTaxon":"Ulva spp.","cue":"Example: Ulva lactuca. Notice the thin, bright green sheet. Similar Ulva species can be hard to distinguish by sight."},{"name":"Cryptopleura spp.","taxon":"Cryptopleura ruprechtiana","photo":43945405,"observation":28201915,"license":"cc-by","credit":"(c) Allison Gong, some rights reserved (CC BY)","image":"","directoryTaxon":"Cryptopleura spp.","cue":"Example: Cryptopleura ruprechtiana. Notice its flattened red blades and irregular margins."},{"name":"Laminaria spp.","taxon":"Laminaria setchellii","photo":291882371,"observation":168423888,"license":"cc-by","credit":"(c) Allison Gong, some rights reserved (CC BY)","image":"","directoryTaxon":"Laminaria spp.","cue":"Example: Laminaria setchellii. This habitat photo shows the kelp growing in a dense bed at low tide."}]);
